import java.util.Scanner;

public class Main {
    static long[] factorials = new long[501];
    static long[] invFactorials = new long[501];
    static long[] dpF = new long[501];
    static long[] dpG = new long[501];
    static long[][][] hArray = new long[501][501][2];
    static long[][] comb = new long[501][501];
    static long totalS, result, tempF;
    static int totalN, totalM, modulus, invModulus;

    static long fast_pow(long base, int power) {
        long res = 1;
        while (power > 0) {
            if ((power & 1) == 1) res = res * base % modulus;
            base = base * base % modulus;
            power >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        totalM = sc.nextInt();
        modulus = sc.nextInt();
        invModulus = modulus - 2;

        factorials[0] = 1;
        for (int idx = 1; idx <= totalN; idx++) {
            factorials[idx] = factorials[idx - 1] * idx % modulus;
        }

        invFactorials[totalN] = fast_pow(factorials[totalN], invModulus);
        for (int idx = totalN - 1; idx >= 0; idx--) {
            invFactorials[idx] = invFactorials[idx + 1] * (idx + 1) % modulus;
        }

        comb[0][0] = 1;
        for (int idx = 1; idx <= totalN; idx++) {
            comb[idx][0] = 1;
            for (int jdx = 1; jdx <= idx; jdx++) {
                comb[idx][jdx] = (comb[idx - 1][jdx - 1] + comb[idx - 1][jdx]) % modulus;
            }
        }

        dpF[0] = 1;
        dpG[0] = 0;

        for (int idx = 1; idx <= totalM; idx++) {
            for (int jdx = 1; jdx <= idx; jdx++) {
                totalS = (long)((jdx * (jdx - 1) / 2 + (idx - jdx + 1) * (idx - jdx) / 2) % modulus);
                dpF[idx] = (dpF[idx] + dpF[jdx - 1] * dpF[idx - jdx] % modulus * (idx + 1) % modulus * comb[idx - 1][jdx - 1]) % modulus;
                long term1 = (dpG[jdx - 1] * dpF[idx - jdx] + dpF[jdx - 1] * dpG[idx - jdx]) % modulus;
                long term2 = (dpF[jdx - 1] * dpF[idx - jdx]) % modulus * totalS % modulus;
                dpG[idx] = (dpG[idx] + ((term1 * (idx + 1) % modulus + term2) % modulus) * comb[idx - 1][jdx - 1]) % modulus;
            }
        }

        for (int i = 0; i < hArray.length; i++) {
            for (int j = 0; j < hArray[0].length; j++) {
                hArray[i][j][0] = 0;
                hArray[i][j][1] = 0;
            }
        }
        hArray[0][0][0] = 1;

        int maxLimit = Math.min(totalM, totalN - totalM + 1);
        for (int idx = 0; idx < maxLimit; idx++) {
            for (int jdx = 0; jdx < totalM; jdx++) {
                for (int kdx = 1; kdx <= totalM - jdx; kdx++) {
                    tempF = dpF[kdx] * comb[jdx + kdx][jdx] % modulus;
                    hArray[idx + 1][jdx + kdx][0] = (hArray[idx + 1][jdx + kdx][0] + hArray[idx][jdx][0] * tempF) % modulus;
                    hArray[idx + 1][jdx + kdx][1] = (hArray[idx + 1][jdx + kdx][1] + hArray[idx][jdx][1] * tempF) % modulus;
                    hArray[idx + 1][jdx + kdx][1] = (hArray[idx + 1][jdx + kdx][1] + hArray[idx][jdx][0] * dpG[kdx] % modulus * comb[jdx + kdx][jdx]) % modulus;
                }
            }
        }

        result = 0;
        for (int idx = 1; idx <= maxLimit; idx++) {
            result = (result + hArray[idx][totalM][1] * comb[totalN - totalM + 1][idx]) % modulus;
        }

        System.out.println(result % modulus);
        sc.close();
    }
}
